        case FrameIndexRole:
            return index.row();
        case XRole:
            return pose.x;
        case YRole:
            return pose.y;
        case ZRole:
            return pose.z;
        case XaRole:
            return pose.xa;
        case YaRole:
            return pose.ya;
        case ZaRole:
            return pose.za;
