    REQUIRE(f.poses()->dirty());
    REQUIRE(f.poses()->validationMessage().isEmpty());
    /*The table model re-reads the stored value (the QML binding surface).*/
    REQUIRE(f.poses()->poseValue(1, 0, 2) == Approx(12.5));

